def product(model_id="dominar-400"):
 return product_page(D,icon,cta,money,model_id)
def privacy():
 return '''<section class="section privacy"><h1>Privacidade e preferências</h1><p>Esta prévia da Bajaj InteriorSP permite consultar produtos e preparar mensagens para o WhatsApp das unidades. Não há cadastro, envio de documentos nem formulário de análise de crédito no site.</p><h2>Escolha de unidade</h2><p>O site guarda a unidade que você escolhe no armazenamento local deste navegador. Essa preferência é usada para direcionar seus contatos e pode ser alterada no seletor do topo.</p><button class="button outline" id="clear-preference">Apagar minha preferência de unidade</button><p id="preference-status" role="status"></p><h2>WhatsApp e links externos</h2><p>Ao continuar para o WhatsApp, a mensagem preparada contém o modelo, preço e, na simulação, entrada e prazo que você informar. Ela só é enviada quando você confirmar no próprio WhatsApp. Não inclua documentos ou dados sensíveis nos campos do site. Google Maps, redes sociais e outros destinos externos seguem as práticas de seus respectivos serviços.</p><h2>Mensuração nesta prévia</h2><p>Não há identificadores de Google Analytics, Tag Manager, Meta Pixel ou Google Ads ativados. Os eventos de navegação preparados no código não incluem os valores informados na simulação nem enviam dados para serviços de análise.</p><h2>Contato</h2><p>Para dúvidas sobre o uso de seus dados no atendimento, entre em contato com a unidade. A política definitiva e os canais específicos para solicitações de privacidade deverão ser confirmados antes do lançamento público.</p><a class="text-link" href="/unidades/">Ver contatos das unidades</a></section>'''
def page(body,title,desc,path,ptype='',model_id=''):
 model=next((m for m in D['models'] if m['id']==model_id),None)
 schema={'@context':'https://schema.org','@graph':[{'@type':'MotorcycleDealer','name':'Bajaj InteriorSP — '+u['name'],'url':'https://bajajinteriorsp.com.br/','telephone':'+'+u['phone'],'address':{'@type':'PostalAddress','streetAddress':u['address'],'postalCode':u['cep'],'addressCountry':'BR'},'hasMap':u['maps']} for u in D['units']]}
 if ptype=='product':
  model=model or next(m for m in D['models'] if m['id']=='dominar-400')
  schema['@graph'].append({'@type':'Product','name':'Bajaj '+model['name'],'brand':{'@type':'Brand','name':'Bajaj'},'model':model['year'],'description':desc,'image':'https://bajajinteriorsp.com.br/assets/'+model['image'],'offers':{'@type':'Offer','priceCurrency':'BRL','price':str(model['price'])+'.00','url':'https://bajajinteriorsp.com.br'+path}})
 return f'''<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{title}</title><meta name="description" content="{esc(desc)}"><meta name="robots" content="noindex,nofollow"><meta name="theme-color" content="#0052a1"><link rel="canonical" href="https://bajajinteriorsp.com.br{path}"><meta property="og:title" content="{title}"><meta property="og:description" content="{esc(desc)}"><meta property="og:type" content="website"><meta property="og:locale" content="pt_BR"><link rel="icon" href="/assets/favicon.png"><link rel="preload" href="/assets/din-regular.otf" as="font" type="font/otf" crossorigin><link rel="stylesheet" href="/styles.css">{'<link rel="stylesheet" href="/journey.css"><script type="module" src="/journey.mjs"></script><link rel="stylesheet" href="/home-hero.css"><script type="module" src="/home-hero.mjs"></script><link rel="stylesheet" href="/home-units-gallery.css"><script type="module" src="/home-units-gallery.mjs"></script><script type="module" src="/family-film.mjs"></script><script type="module" src="/closing-film.mjs"></script><link rel="stylesheet" href="/home-art-slider.css"><script type="module" src="/home-art-slider.mjs"></script><link rel="stylesheet" href="/home-reveal.css"><script type="module" src="/home-reveal.mjs"></script>' if ptype=='home' else ''}{'<link rel="stylesheet" href="/dominar-400.css"><script type="module" src="/dominar-400.mjs"></script>' if ptype=='product' else ''}{'<link rel="stylesheet" href="/service-pages.css"><script type="module" src="/service-request.mjs"></script>' if ptype=='service' else ''}<script type="application/ld+json">{json.dumps(schema,ensure_ascii=False)}</script><script type="module" src="/app.mjs"></script>{'<link rel="stylesheet" href="/offers.css"><script type="module" src="/offers.mjs"></script>' if path=='/ofertas/' else ''}</head><body data-page="{ptype}" data-model="{model['id'] if model else ''}">{header()}<main id="conteudo">{body}</main>{footer(model)}<noscript><div class="noscript">Para usar a seleção de unidade e os formulários, ative o JavaScript. Atendimento direto: <a href="https://wa.me/5517992606039">Rio Preto</a> ou <a href="https://wa.me/5514996448094">Bauru</a>.</div></noscript></body></html>'''
pages=[('/',home(),'Bajaj InteriorSP | Motos em Rio Preto e Bauru','Conheça a linha Bajaj, consulte preços e fale com a BIA de São José do Rio Preto ou Bauru. Solicite simulação e test ride.','home',''),('/privacidade/',privacy(),'Privacidade e preferências | Bajaj InteriorSP','Saiba como funciona a escolha de unidade e o contato pelo WhatsApp nesta prévia da Bajaj InteriorSP.','privacy','')]
for m in D['models']:
 desc='Dominar 400 2026/2027: 373,27 cc, 40 CV e quatro modos de pilotagem. Conheça os detalhes e fale com a BIA em Rio Preto ou Bauru.' if m['id']=='dominar-400' else f"{m['name']} {m['year']}: conheça preço, fotos e ficha técnica. Solicite simulação ou test ride com a BIA em Rio Preto ou Bauru."
 pages.append((f"/motos/{m['id']}/",product(m['id']),f"{m['name']} | {money(m['price'])} | Bajaj InteriorSP",desc,'product',m['id']))
for kind in ['ofertas','financiamento','test-ride','pos-venda','unidades','a-interiorsp']:
 body,title,desc=support_page(kind,D,icon,cta,money,finance,units)
 pages.append((f'/{kind}/',body,title+' em Rio Preto e Bauru | Bajaj InteriorSP',desc,'service',''))
for path,body,title,desc,typ,model_id in pages:
 dest=out/path.strip('/');dest.mkdir(parents=True,exist_ok=True);(dest/'index.html').write_text(page(body,title,desc,path,typ,model_id))
shutil.copy(P/'data.json',out/'data.json')
(out/'robots.txt').write_text('User-agent: *\nDisallow: /\n')
(out/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join('<url><loc>https://bajajinteriorsp.com.br'+p[0]+'</loc></url>' for p in pages if p[0]!='/privacidade/')+'</urlset>')
print(f'Geradas {len(pages)} páginas. Dados centralizados; preços preservados do briefing.')
